add('table-01',5,[99,66,1091,271],'Measured and fitted structural summary','Table compares TEM size/aspect ratio, WDS composition and SAXS/WAXS fit results for the main coverage series.',MAIN+' '+SERIES,kind='table',evidence='mixed_measurement_and_fit',notes=['TEM size is the longest particle dimension (major axis), not an isotropic diameter or separately measured core diameter.','SAXS sizes and SAXS/WAXS Zn/Cd columns are calculated/fitted, whereas TEM and WDS columns are measured.','Blank cells are unreported, never zero. The two thicker-shell SAXS patterns were not confidently fitted.'])
