add('formula-guinier-context',8,[99,1215,578,1415],'Guinier relation as printed','Unnumbered intensity, form-factor and Guinier expressions embedded in their explanatory text.','Context for the separate solution-SAXS series.',kind='unnumbered_formula_context',evidence='analytical_model',notes=['The source prints exp(−q²RG²/5) and calls RG the Guinier radius for spherical particles. Preserve literally; do not silently substitute a conventional formula or redefine its symbol.'])
